insert into public.sessions (id, subject_id, faculty_id, date, status, source, hours, activities, homework, summary, notes) values
  ('ss1', 's-chem', 'f1', '2026-09-21', 'verified', 'seed', 2, 'Timeline discussion, two numerical problems', 'Read Chapter 2', 'Completed atomic models from Dalton to Bohr.', null),
  ('ss2', 's-chem', 'f1', '2026-09-28', 'verified', 'seed', 2, 'Aufbau practice, five configurations written', 'Periodic table worksheet', 'Finished electronic configuration; began periodic trends.', '{"keyConcepts":["Aufbau principle","Hund''s rule","Pauli exclusion principle"],"detail":["Orbitals fill from lowest to highest energy.","Electrons occupy degenerate orbitals singly before pairing."],"examples":["Fe: [Ar] 3d6 4s2","Cu: [Ar] 3d10 4s1 (exception)"],"sources":["Faculty-provided slides","Approved textbook: Chemistry Fundamentals, Ch. 3"]}'::jsonb),
  ('ss3', 's-chem', 'f1', '2026-10-01', 'missed', 'seed', 0, '', '', 'Session not held; faculty on leave.', null),
  ('ss4', 's-chem', 'f1', '2026-10-05', 'pending', 'seed', 2, '', '', 'Class held but the record has not been verified.', null),
  ('ss5', 's-chem', 'f1', '2026-10-08', 'verified', 'seed', 2, 'Trend graphs, three worked examples', 'Ionic compound formation exercises', 'Finished periodic trends; introduced ionic bonding.', '{"keyConcepts":["Ionization energy","Electronegativity","Ionic bond formation"],"detail":["Ionization energy increases across a period and decreases down a group.","Ionic bonds form through electron transfer between metals and non-metals."],"examples":["NaCl formation","MgO lattice discussion"],"sources":["Faculty-provided slides","Approved textbook: Chemistry Fundamentals, Ch. 4"]}'::jsonb),
  ('ss6', 's-math', 'f2', '2026-10-07', 'verified', 'seed', 2, 'Cofactor expansion drills', 'Problem set 6', 'Completed determinants and properties.', null),
  ('ss7', 's-math', 'f2', '2026-10-09', 'verified', 'seed', 1, 'Characteristic polynomial examples', 'Find eigenvalues of three 2x2 matrices', 'Introduced eigenvalues and the characteristic equation.', '{"keyConcepts":["Characteristic equation","Eigenvalue and eigenvector","det(A − λI) = 0"],"detail":["An eigenvector keeps its direction under the transformation.","Eigenvalues are roots of the characteristic polynomial."],"examples":["A = [[2,1],[1,2]] gives λ = 1, 3"],"sources":["Faculty-provided slides","Approved textbook: Linear Algebra Essentials, Ch. 5"]}'::jsonb),
